package com.sih.analytics.service; import com.sih.analytics.dto.AnalyticsDtos.*; import com.sih.analytics.entity.*; import com.sih.analytics.repo.*; import com.sih.shared.tenant.TenantContext; import java.time.*; import java.util.*; import java.util.stream.*; import org.springframework.http.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.*; import org.springframework.web.server.*; @Service @Transactional public class AnalyticsService{final MetricRepository repo;public AnalyticsService(MetricRepository r){repo=r;}String t(){return TenantContext.requireCurrentTenant();}public MetricResponse record(MetricRequest r){if(!Set.of("CLINICAL","FINANCIAL","OPERATIONAL").contains(r.category()))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Catégorie invalide");MetricSnapshot x=new MetricSnapshot();x.setCategory(r.category());x.setMetricKey(r.metricKey());x.setLabel(r.label());x.setValue(r.value());x.setUnit(r.unit());x.setMeasuredAt(r.measuredAt()==null?OffsetDateTime.now():r.measuredAt());x.setSourceService(r.sourceService());return map(repo.save(x));}public List<MetricResponse> list(){return repo.findByTenantIdOrderByMeasuredAtDesc(t()).stream().map(this::map).toList();}public DashboardResponse dashboard(){Map<String,MetricResponse> latest=list().stream().collect(Collectors.toMap(MetricResponse::metricKey,x->x,(a,b)->a,LinkedHashMap::new));var values=latest.values();return new DashboardResponse(values.stream().filter(x->x.category().equals("CLINICAL")).toList(),values.stream().filter(x->x.category().equals("FINANCIAL")).toList(),values.stream().filter(x->x.category().equals("OPERATIONAL")).toList(),OffsetDateTime.now());}MetricResponse map(MetricSnapshot x){return new MetricResponse(x.getId(),x.getCategory(),x.getMetricKey(),x.getLabel(),x.getValue(),x.getUnit(),x.getMeasuredAt(),x.getSourceService());}}